mapper.select:
SELECT paged_data.id, paged_data.device_id, paged_data.device_iemi, paged_data.device_type, paged_data.record_timestamp, paged_data.organization_code, paged_data.speed, paged_data.seeding_area, paged_data.on_duty, paged_data.imei, paged_data.longitude, paged_data.latitude, paged_data.province, paged_data.city, paged_data.district, paged_data.township, paged_data.full_address, paged_data.update_time, sensor.robot_id, sensor.name, sensor.value, user_info.owner_name, user_info.owner_number FROM ( SELECT latest_data.id, latest_data.device_id, latest_data.device_iemi, latest_data.device_type, latest_data.record_timestamp, latest_data.organization_code, latest_data.speed, latest_data.seeding_area, latest_data.on_duty, latest_data.imei, latest_data.longitude, latest_data.latitude, latest_data.province, latest_data.city, latest_data.district, latest_data.township, latest_data.full_address, latest_data.update_time FROM ( SELECT s.id, s.device_id, s.device_iemi, s.device_type, s.record_timestamp, s.organization_code, s.speed, s.seeding_area, s.on_duty, g.imei, g.longitude, g.latitude, g.province, g.city, g.district, g.township, g.full_address, g.update_time, ROW_NUMBER() OVER (PARTITION BY s.device_iemi ORDER BY s.record_timestamp DESC) as rn FROM seeding_robot_general_data s INNER JOIN latest_geo_location_info g ON s.device_iemi = g.imei ) latest_data WHERE latest_data.rn = 1
AND latest_data.city = #{city}
AND latest_data.on_duty = #{status}
ORDER BY latest_data.record_timestamp DESC LIMIT #{limit} OFFSET #{offset} ) paged_data LEFT JOIN seeding_robot_sensor_data sensor ON paged_data.id = sensor.robot_id LEFT JOIN seeding_robot_user_info user_info ON paged_data.device_iemi = user_info.device_imei ORDER BY paged_data.record_timestamp DESC, sensor.name

SELECT COUNT(*) FROM seeding_robot_general_data s INNER JOIN latest_geo_location_info g ON s.device_iemi = g.imei INNER JOIN ( SELECT device_iemi, MAX(record_timestamp) AS latest_timestamp FROM seeding_robot_general_data GROUP BY device_iemi ) latest ON s.device_iemi = latest.device_iemi AND s.record_timestamp = latest.latest_timestamp
AND g.city = #{city}
AND s.on_duty = #{status}
